<?php
declare(strict_types=1);
require __DIR__.'/common.php';$u=cloud_user();$d=db();try{$p=music_playlist($d,music_id($_GET['id']??null),(int)$u['id']);}catch(InvalidArgumentException){$p=null;}
if(!$p){$d->close();http_response_code(404);head('Nie znaleziono playlisty');echo '<a class="btn btn-primary" href="playlists.php">Moje playlisty</a>';foot();exit;}
$owner=(int)$p['idu']===(int)$u['id'];
$s=$d->prepare('SELECT s.*,m.name AS genre,u.username,x.idpldb FROM z6_playlistdatabase x JOIN z6_song s ON s.ids=x.ids JOIN z6_musictype m ON m.idmt=s.idmt JOIN z6_users u ON u.id=s.idu WHERE x.idpl=? ORDER BY x.idpldb');$s->bind_param('i',$p['idpl']);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();$own=music_own_playlists($d,(int)$u['id']);
$available=[];if($owner){$s=$d->prepare('SELECT s.ids,s.title,s.musician FROM z6_song s WHERE '.music_access_sql().' AND NOT EXISTS(SELECT 1 FROM z6_playlistdatabase x WHERE x.idpl=? AND x.ids=s.ids) ORDER BY s.title,s.ids');$s->bind_param('iii',$u['id'],$u['id'],$p['idpl']);$s->execute();$available=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}$d->close();
$queue=array_map(fn($s)=>['id'=>(int)$s['ids'],'title'=>$s['title'],'musician'=>$s['musician'],'url'=>'song_file.php?id='.(int)$s['ids']],$rows);
head($p['name']);music_toolbar($owner?'playlists.php':'playlists.php?public=1');
?>
<div class="d-flex flex-wrap gap-3 align-items-center mb-4"><?=music_cover_html(null,(int)$p['idpl'],$p['coverfilename'],'Okładka '.$p['name'],true)?><span class="badge <?=$p['public']?'text-bg-success':'text-bg-secondary'?>"><?=$p['public']?'Publiczna':'Prywatna'?></span><span class="text-body-secondary"><?=h($p['username'])?> · <?=count($rows)?> utworów · <?=h(cloud_time($p['datetime']))?></span></div>
<?php if($rows): ?>
<section class="mb-4 music-player" data-queue="<?=h(json_encode($queue,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR))?>"><button class="btn btn-primary" id="play-playlist" type="button">▶ Odtwórz playlistę</button></section>
<div class="list-group mb-4"><?php foreach($rows as $i=>$song): ?><article class="list-group-item music-track" data-row="<?=$i?>"><div class="d-flex flex-wrap justify-content-between align-items-center gap-3"><div class="d-flex align-items-center gap-3"><button type="button" class="btn btn-outline-primary music-track-play" data-track="<?=$i?>" aria-label="Odtwórz <?=h($song['title'])?>"><?=$i+1?> ▶</button><div><a href="song.php?id=<?=$song['ids']?>" class="fw-semibold"><?=h($song['title'])?></a><div class="small text-body-secondary"><?=h($song['musician'])?> · <?=h($song['genre'])?></div></div></div><div class="d-flex flex-wrap align-items-center gap-2"><?php if($owner): ?><form method="post" action="music_action.php" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=h(music_csrf())?>"><input type="hidden" name="action" value="remove_song"><input type="hidden" name="playlist" value="<?=$p['idpl']?>"><input type="hidden" name="song" value="<?=$song['ids']?>"><button class="btn btn-outline-danger btn-sm" type="submit" aria-label="Usuń <?=h($song['title'])?> z playlisty">Usuń z playlisty</button></form><?php else: music_add_form($song,$own,(int)$p['idpl']); endif; ?></div></div></article><?php endforeach; ?></div>
<?php else: ?><div class="card card-body text-center py-4 mb-4"><p class="mb-0">Ta playlista jest pusta.</p></div><?php endif; ?>
<?php if($owner): ?>
<?php if($available): ?><section class="card mb-4"><div class="card-body p-4"><h2 class="h5 mb-3">Dodaj utwór do playlisty</h2><form method="post" action="music_action.php" class="d-flex flex-wrap gap-2"><input type="hidden" name="csrf" value="<?=h(music_csrf())?>"><input type="hidden" name="action" value="add_song"><input type="hidden" name="playlist" value="<?=$p['idpl']?>"><label class="visually-hidden" for="add-existing-song">Utwór</label><select class="form-select music-track-select" id="add-existing-song" name="song" required><option value="">Wybierz utwór</option><?php foreach($available as $song): ?><option value="<?=$song['ids']?>"><?=h($song['title'].' — '.$song['musician'])?></option><?php endforeach; ?></select><button class="btn btn-primary" type="submit">Dodaj do playlisty</button></form></div></section><?php endif; ?>
<details class="card"><summary class="p-3">Ustawienia playlisty</summary><div class="card-body p-4 pt-0"><form method="post" action="music_action.php" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=h(music_csrf())?>"><input type="hidden" name="action" value="update_playlist"><input type="hidden" name="playlist" value="<?=$p['idpl']?>"><label class="form-label" for="edit-playlist-name">Nazwa</label><input class="form-control mb-3" name="name" id="edit-playlist-name" value="<?=h($p['name'])?>" maxlength="160" required><div class="form-check mb-3"><input class="form-check-input" type="checkbox" id="playlist-public" name="public" value="1"<?=$p['public']?' checked':''?>><label class="form-check-label" for="playlist-public">Playlista publiczna</label></div><label class="form-label" for="edit-playlist-cover">Nowa okładka (opcjonalnie)</label><input class="form-control mb-3" type="file" id="edit-playlist-cover" name="cover" accept="image/png,image/jpeg,image/webp"><button class="btn btn-primary" type="submit">Zapisz ustawienia</button></form><hr><form method="post" action="music_action.php" class="music-delete" data-confirm="Usunąć playlistę?"><input type="hidden" name="csrf" value="<?=h(music_csrf())?>"><input type="hidden" name="action" value="delete_playlist"><input type="hidden" name="playlist" value="<?=$p['idpl']?>"><button class="btn btn-outline-danger" type="submit">Usuń playlistę</button></form></div></details>
<?php endif; ?>
<?php foot(); ?>
